using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Accounts.Dtos;using Namaa.Domain.Common.Results;namespace Namaa.Application.Accounts.Queries.GetAccounts;public sealed class GetAccountsQueryHandler(IAccountRepository repository):IRequestHandler<GetAccountsQuery,Result<IReadOnlyList<AccountDto>>>{public async Task<Result<IReadOnlyList<AccountDto>>>Handle(GetAccountsQuery request,CancellationToken cancellationToken)=>Result.Success<IReadOnlyList<AccountDto>>((await repository.GetAllAsync(cancellationToken)).Select(AccountDto.FromEntity).ToList());}
